317	    /**
318	     * Whether this owner's city already holds between 40 and 49 owners (inclusive), approaching the
319	     * hard capacity limit of 50. Derived at response time and not persisted; {@code true} triggers a
320	     * capacity warning in the response.
321	     */
322	    public Boolean getCapacityWarning() {
323	        return this.capacityWarning;
324	    }
325	
326	    public void setCapacityWarning(Boolean capacityWarning) {
327	        this.capacityWarning = capacityWarning;
328	    }
