330	    /**
331	     * The number of owners in this owner's household (owners sharing the same
332	     * {@link #householdId}), derived at response time and not persisted.
333	     */
334	    public Integer getHouseholdSize() {
335	        return this.householdSize;
336	    }
337	
338	    public void setHouseholdSize(Integer householdSize) {
339	        this.householdSize = householdSize;
340	    }
341	
342	    /**
343	     * The ceiling applied to {@link #getMembershipLevel() membershipLevel}: one above the current
344	     * maximum membershipLevel among this owner's existing household members. Derived at response
345	     * time and not persisted; {@code null} means no household member exists and no cap applies.
346	     */
347	    public Integer getMembershipLevelCap() {
348	        return this.membershipLevelCap;
349	    }
350	
351	    public void setMembershipLevelCap(Integer membershipLevelCap) {
352	        this.membershipLevelCap = membershipLevelCap;
353	    }
354	
355	    /**
356	     * The owner's membership points, derived at response time. Starts at {@code 0}, plus 2 when an
357	     * email is present, plus 1 when {@link #namesakeCount} is 0, plus 2 when the
358	     * {@link #getHouseholdSize() household} has 3 or more members, plus 3 when tenure exceeds one
359	     * elapsed fiscal year (measured from the {@link #registrationDate}; see
360	     * {@link #getTenureFiscalYears()}).
361	     */
362	    public Integer getMembershipPoints() {
363	        int points = 0;
364	        if (this.email != null && !this.email.isEmpty()) {
365	            points += 2;
366	        }
367	        if (this.namesakeCount != null && this.namesakeCount == 0) {
368	            points += 1;
369	        }
370	        if (this.householdSize != null && this.householdSize >= 3) {
371	            points += 2;
372	        }
373	        if (getTenureFiscalYears() > 1) {
374	            points += 3;
375	        }
376	        return points;
377	    }
378	
379	    /**
380	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints() membershipPoints}:
381	     * {@code 1} for 0-1 points, {@code 2} for 2-3 points, {@code 3} for 4-5 points, and {@code 4} for
382	     * 6 or more points.
383	     *
384	     * <p>When a {@link #getMembershipLevelCap() membershipLevelCap} is present the result is capped to
385	     * it, so a new owner's level cannot exceed one above the current maximum membershipLevel among
386	     * their household members. With no household member the cap is absent and the mapped level stands.
387	     */
388	    public Integer getMembershipLevel() {
389	        int points = getMembershipPoints();
390	        int level;
391	        if (points <= 1) {
392	            level = 1;
393	        }
394	        else if (points <= 3) {
395	            level = 2;
396	        }
397	        else if (points <= 5) {
398	            level = 3;
399	        }
400	        else {
401	            level = 4;
402	        }
403	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
404	            return this.membershipLevelCap;
405	        }
406	        return level;
407	    }
408	
409	    /**
410	     * The fiscal year containing {@code date}: fiscal years start on 1 July and are named for the
411	     * calendar year in which they end, so 1 July 2026 – 30 June 2027 is fiscal year {@code 2027}.
412	     */
413	    public static int fiscalYear(LocalDate date) {
414	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
415	    }
416	
417	    /**
418	     * The owner's fiscal year, derived at response time from the {@code FY} segment of the
419	     * {@link #getMemberId() memberId} (the two digits following the REGION prefix) as {@code FY<YY>},
420	     * where the fiscal year starts on 1 July and {@code YY} is the last two digits of the fiscal
421	     * year (the calendar year in which it ends). Because the member id embeds the fiscal year of the
422	     * business-day-adjusted {@link #registrationDate} at creation, the value tracks the member id.
423	     * {@code null} when the owner has no member id. Not persisted.
424	     */
425	    public String getFiscalYear() {
426	        if (this.memberId == null) {
427	            return null;
428	        }
429	        int start = getLocality().length();
430	        if (this.memberId.length() < start + 2) {
431	            return null;
432	        }
433	        return "FY" + this.memberId.substring(start, start + 2);
434	    }
435	
436	    /**
437	     * The owner's tenure in elapsed fiscal years, measured from the {@link #registrationDate}'s
438	     * fiscal year to the current fiscal year (fiscal years start on 1 July); zero when the
439	     * registration date is absent or falls in a later fiscal year than today.
440	     */
441	    private long getTenureFiscalYears() {
442	        if (this.registrationDate == null) {
443	            return 0;
444	        }
445	        long years = (long) fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate);
446	        return Math.max(years, 0);
447	    }
