472	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
473	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
474	     * absent, not a 4-digit number, or in no known range.
475	     */
476	    public static String regionOfPostcode(String postcode) {
477	        if (postcode == null || postcode.isEmpty()) {
478	            return null;
479	        }
480	        int value;
481	        try {
482	            value = Integer.parseInt(postcode);
483	        } catch (NumberFormatException ex) {
484	            return null;
485	        }
486	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
487	            int[] range = entry.getValue();
488	            if (value >= range[0] && value <= range[1]) {
489	                return entry.getKey();
490	            }
491	        }
492	        return null;
493	    }
