495	    /**
496	     * The owner's region, derived at response time from the {@code REGION} prefix of the
497	     * {@link #getMemberId() memberId} (the leading run of letters before the two-digit fiscal year).
498	     * Because the member id is assigned as {@code <REGION><FY><HASH8><CHK>} with REGION taken from the
499	     * postcode, the locality follows the same region-and-hash identity as the member id.
500	     * {@code UNKNOWN} when the owner has no member id.
501	     */
502	    public String getLocality() {
503	        if (this.memberId == null) {
504	            return "UNKNOWN";
505	        }
506	        int i = 0;
507	        while (i < this.memberId.length() && Character.isLetter(this.memberId.charAt(i))) {
508	            i++;
509	        }
510	        return i == 0 ? "UNKNOWN" : this.memberId.substring(0, i);
511	    }
