513	    /**
514	     * The owner's IANA timezone name, derived at response time from the {@link #getLocality()
515	     * locality}/region via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
516	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null}
517	     * when the region is not in the table. Not persisted.
518	     */
519	    public String getTimezone() {
520	        return REGION_TIMEZONE.get(getLocality());
521	    }
522	
523	    /**
524	     * The owner's segment, derived at response time as {@code <TIER>_<AREA>} — one of
525	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
526	     * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when {@link #getMembershipLevel()
527	     * membershipLevel} is 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO} when the
528	     * {@link #getLocality() locality} is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
529	     * otherwise {@code REGIONAL}. Not persisted.
530	     */
531	    public String getOwnerSegment() {
532	        Integer level = getMembershipLevel();
533	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
534	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
535	        return tier + "_" + area;
