538	    /**
539	     * The owner's preferred contact channel, derived at response time: {@code EMAIL} when an
540	     * email is present, otherwise {@code PHONE}. Not persisted.
541	     */
542	    public String getContactPreference() {
543	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
