2	
3	import java.util.Objects;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Flags the new owner as a possible (soft) duplicate. With duplicate detection now keyed off the
11	 * single {@link Owner#getIdentityKey() identityKey} (handled as a 409 in {@link DetectOwnerDuplicate}),
12	 * the soft signal catches the near-miss that the key deliberately lets through: an earlier non-deleted
13	 * owner whose {@link Owner#soundex(String) soundex(lastName)} and postcode both match this owner's,
14	 * but whose identity key differs.
15	 *
16	 * <p>Because the telephone (and email) are part of the identity key, two owners sharing a last name
17	 * and postcode but differing in telephone or email have different keys — so they are not a hard
18	 * duplicate (no 409); they surface here as a soft match instead.
19	 *
20	 * <p>Runs after {@link BuildOwner} and {@link DetectOwnerDuplicate} (so a hard duplicate has already
21	 * been rejected) and before {@link SaveOwner}, scanning only pre-existing (already persisted) owners —
22	 * the new owner has no id yet and is skipped. The earliest such match (lowest id) is recorded:
23	 * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to that owner's id; otherwise
24	 * {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left null. Both are stored on
25	 * the built owner so the saved and returned record carries them.
26	 */
27	public class DetectOwnerPossibleDuplicate {
28	
29	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
30	        String soundex = Owner.soundex(owner.getLastName());
31	        String postcode = owner.getPostcode();
32	        String identityKey = owner.getIdentityKey();
33	        Owner match = null;
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (existing.getId() == null) {
36	                continue; // an unsaved owner (including the new one) has no id to record
37	            }
38	            if (existing.getId().equals(owner.getId())) {
39	                continue; // the owner itself is never its own duplicate
40	            }
41	            if (existing.isDeleted()) {
42	                continue; // soft-deleted owners are ignored
43	            }
44	            if (!soundex.equals(Owner.soundex(existing.getLastName()))) {
45	                continue; // last names must be phonetically equal
46	            }
47	            if (!Objects.equals(postcode, existing.getPostcode())) {
48	                continue; // and share a postcode
49	            }
50	            if (identityKey.equals(existing.getIdentityKey())) {
51	                continue; // an exact identity match is a hard duplicate, not a soft one
52	            }
53	            if (match == null || existing.getId() < match.getId()) {
54	                match = existing;
55	            }
56	        }
57	        if (match != null) {
58	            owner.setPossibleDuplicate(true);
59	            owner.setPossibleDuplicateOf(match.getId());
60	        }
61	        else {
62	            owner.setPossibleDuplicate(false);
63	            owner.setPossibleDuplicateOf(null);
64	        }
65	    }
66	}
