3	import java.util.Locale;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
9	
10	/**
11	 * Rejects an owner whose email domain is on the disposable-domain blocklist. Email is optional, so
12	 * an absent (null/blank) email is skipped; a present but syntactically invalid address is already
13	 * rejected 400 by the {@code @Email} constraint at {@link ValidateOwner}. Runs after
14	 * {@link NormalizeOwnerEmail} has lower-cased the address, so the domain comparison is
15	 * case-insensitive. A blocklisted domain is rejected 400 via {@link DisposableEmailDomainException}.
16	 */
17	public class ValidateOwnerEmailDomain {
18	
19	    /** Disposable email domains that are not accepted for owner registration. */
20	    private static final Set<String> BLOCKED_DOMAINS =
21	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
22	
23	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
24	        String email = request.getEmail();
25	        if (email == null) {
26	            return; // optional when absent
27	        }
28	        int at = email.lastIndexOf('@');
29	        if (at < 0 || at == email.length() - 1) {
30	            return; // no domain part; syntactic validity is enforced by @Email at ValidateOwner
31	        }
32	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
33	        if (BLOCKED_DOMAINS.contains(domain)) {
34	            throw new DisposableEmailDomainException(
35	                "Email domain " + domain + " is not accepted (disposable-domain blocklist)");
36	        }
37	    }
38	}
