7	/**
8	 * Derives the owner's {@code capacityWarning} at response time: {@code true} when the owner's city
9	 * already holds between {@value #WARN_THRESHOLD} and {@link CheckOwnerCityCapacity#CITY_CAPACITY}-1
10	 * owners (inclusive) — the band approaching the hard capacity limit that
11	 * {@link CheckOwnerCityCapacity} enforces — otherwise {@code false}. The per-city count is
12	 * delegated to {@link CheckOwnerCityCapacity#countInCity(OwnerRepository, String)} — the same unit
13	 * the 409 gate rejects on — so the warning provably tracks the same population that gate governs.
14	 *
15	 * <p>Wired into both the create pipeline (where the signal originates) and the single-owner GET
16	 * pipeline, mirroring {@link DeriveOwnerBulkSignupWarning}, so {@code capacityWarning} is populated
17	 * (never null) on reads as well as on the create response. The flag is transient and set on the
18	 * in-flight owner so the responder carries it; it is not persisted.
19	 */
20	public class DeriveOwnerCapacityWarning {
21	
22	    static final int WARN_THRESHOLD = 40;
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        long inCity = CheckOwnerCityCapacity.countInCity(ownerRepository, owner.getCity());
26	        owner.setCapacityWarning(inCity >= WARN_THRESHOLD && inCity < CheckOwnerCityCapacity.CITY_CAPACITY);
27	    }
28	}
