546	    /**
547	     * The owner's deterministic identity key: the full lower-case hex SHA-256 of
548	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The telephone is
549	     * stored in canonical E.164 form and the email lower-cased; an absent telephone or email
550	     * contributes an empty segment, and the last name is reduced to its {@link #soundex(String)
551	     * Soundex} code. Two owners share an identity exactly when this 64-character hex value is equal.
552	     *
553	     * <p>This is the single key duplicate detection keys off: a create is rejected 409 when a
554	     * non-deleted owner already carries the same identity key (see {@code DetectOwnerDuplicate}).
555	     * Because the telephone participates in the key, two owners with the same last name and postcode
556	     * but different telephones no longer collide here — they are flagged as a soft match instead (see
557	     * {@code DetectOwnerPossibleDuplicate}). Derived at response time and not persisted.
558	     */
559	    public String getIdentityKey() {
560	        String telephone = keyPart(this.telephone);
561	        String email = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
562	        String input = telephone + "|" + email + "|" + soundex(this.lastName);
563	        return sha256Hex(input);
564	    }
