566	    private static String keyPart(String value) {
567	        return value == null ? "" : value;
568	    }
569	
570	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
571	    private static String sha256Hex(String value) {
572	        try {
573	            byte[] digest = MessageDigest.getInstance("SHA-256")
574	                    .digest(value.getBytes(StandardCharsets.UTF_8));
575	            StringBuilder sb = new StringBuilder(digest.length * 2);
576	            for (byte b : digest) {
577	                sb.append(String.format("%02x", b));
578	            }
579	            return sb.toString();
580	        }
581	        catch (NoSuchAlgorithmException ex) {
582	            throw new IllegalStateException("SHA-256 not available", ex);
583	        }
584	    }
585	
586	    /**
587	     * The American Soundex code for {@code name}: the retained first letter followed by up to three
588	     * digits mapping the remaining consonants (b/f/p/v→1, c/g/j/k/q/s/x/z→2, d/t→3, l→4, m/n→5, r→6),
589	     * right-padded with zeros to length four. Adjacent duplicate codes collapse; {@code h}/{@code w}
590	     * do not separate repeated codes while vowels (and {@code y}) do. Non-letters are ignored. Returns
591	     * {@code ""} when {@code name} is null or has no letters. Two last names that sound alike share a
592	     * code, which is how the identity key and soft-match group surnames phonetically.
593	     */
594	    public static String soundex(String name) {
595	        if (name == null) {
596	            return "";
597	        }
598	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
599	        if (letters.isEmpty()) {
600	            return "";
601	        }
602	        StringBuilder code = new StringBuilder();
603	        code.append(letters.charAt(0));
604	        char prev = soundexDigit(letters.charAt(0));
605	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
606	            char c = letters.charAt(i);
607	            if (c == 'H' || c == 'W') {
608	                continue; // ignored and does not separate repeated codes
609	            }
610	            char digit = soundexDigit(c);
611	            if (digit != '0' && digit != prev) {
612	                code.append(digit);
613	            }
614	            prev = digit; // a vowel resets prev so a later same code is emitted again
615	        }
616	        while (code.length() < 4) {
617	            code.append('0');
618	        }
619	        return code.toString();
620	    }
621	
622	    /** The Soundex digit for an upper-case letter, {@code '0'} for vowels and {@code h}/{@code w}. */
623	    private static char soundexDigit(char c) {
624	        switch (c) {
625	            case 'B': case 'F': case 'P': case 'V':
626	                return '1';
627	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
628	                return '2';
629	            case 'D': case 'T':
630	                return '3';
631	            case 'L':
632	                return '4';
633	            case 'M': case 'N':
634	                return '5';
635	            case 'R':
636	                return '6';
637	            default:
638	                return '0';
639	        }
640	    }
641	
642	    /**
643	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
644	     * national digits (everything after the country code) grouped in threes and space-separated —
645	     * e.g. {@code +61412345678} becomes {@code +61 412 345 678}. The country code is recognised for
646	     * '+61' (2 digits) and '+1' (1 digit); any other prefix falls back to a 2-digit country code.
647	     * {@code null} when the telephone is absent or not a valid E.164 value. Derived at response time
648	     * and not persisted; the raw {@link #getTelephone() telephone} stays in E.164 form.
649	     */
650	    public String getTelephoneDisplay() {
651	        if (this.telephone == null || !this.telephone.matches("\\+\\d{8,15}")) {
652	            return null;
653	        }
654	        String digits = this.telephone.substring(1);
655	        int countryCodeLength;
656	        if (digits.startsWith("61")) {
657	            countryCodeLength = 2;
658	        }
659	        else if (digits.startsWith("1")) {
660	            countryCodeLength = 1;
661	        }
662	        else {
663	            countryCodeLength = 2;
664	        }
665	        String countryCode = digits.substring(0, countryCodeLength);
666	        String national = digits.substring(countryCodeLength);
667	        StringBuilder display = new StringBuilder("+").append(countryCode);
668	        for (int i = 0; i < national.length(); i += 3) {
669	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
670	        }
671	        return display.toString();
672	    }
673	
674	    protected Set<Pet> getPetsInternal() {
675	        if (this.pets == null) {
676	            this.pets = new HashSet<>();
677	        }
678	        return this.pets;
679	    }
680	
681	    protected void setPetsInternal(Set<Pet> pets) {
682	        this.pets = pets;
683	    }
684	
685	    public List<Pet> getPets() {
686	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
687	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
688	        return Collections.unmodifiableList(sortedPets);
689	    }
690	
691	    public void setPets(List<Pet> pets) {
692	        this.pets = new HashSet<>(pets);
693	    }
694	
695	    public void addPet(Pet pet) {
696	        getPetsInternal().add(pet);
697	        pet.setOwner(this);
698	    }
699	
700	    /**
701	     * Return the Pet with the given name, or null if none found for this Owner.
702	     *
703	     * @param name to test
704	     * @return true if pet name is already in use
705	     */
706	    public Pet getPet(String name) {
707	        return getPet(name, false);
708	    }
709	
710	    /**
711	     * Return the Pet with the given name, or null if none found for this Owner.
712	     *
713	     * @param name to test
714	     * @return true if pet name is already in use
715	     */
716	    public Pet getPet(String name, boolean ignoreNew) {
717	        name = name.toLowerCase();
718	        for (Pet pet : getPetsInternal()) {
719	            if (!ignoreNew || !pet.isNew()) {
720	                String compName = pet.getName();
721	                compName = compName.toLowerCase();
722	                if (compName.equals(name)) {
723	                    return pet;
724	                }
725	            }
726	        }
727	        return null;
728	    }
729	
730	    public Pet getPet(Integer petId) {
731	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
732	    }
733	
734	    @Override
735	    public String toString() {
736	        return new ToStringCreator(this)
737	
738	            .append("id", this.getId())
739	            .append("new", this.isNew())
740	            .append("lastName", this.getLastName())
741	            .append("firstName", this.getFirstName())
742	            .append("address", this.address)
743	            .append("city", this.city)
744	            .append("telephone", this.telephone)
745	            .append("email", this.email)
746	            .toString();
747	    }
748	}
